#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT EnvironmentalSensor : 3
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1
COMPONENT Sound : 3
COMPONENT Text : 2

Viewpoint {
  position 0 0 0
}

Sound {
  location 0 0 -5
  minBack 20
  minFront 20
  maxBack 40
  maxFront 40
  source DEF O AudioClip {
    url "media/tone48k-stereo.wav"
    startTime 946684801.048
    stopTime 1
  }
}

DEF T TimeSensor {
  cycleInterval 0.5
  loop TRUE
}

DEF S Script {
  inputOnly      SFTime  set_time
  outputOnly     SFTime  start
  initializeOnly SFInt32 n 149

  url "javascript:
function set_time (value) { if (++ n === 12) start = value; }
"
}

DEF K Script {
  initializeOnly SFNode  o USE O
  inputOnly      SFTime  set_time
  initializeOnly SFInt32 n 149

  url "javascript:
function set_time (value) { ++ n;
   if (n === 12) { o.startTime = value + 1; }
}
"
  directOutput TRUE
}

DEF PO Script {
  inputOnly SFBool a
  inputOnly SFTime d
  inputOnly SFTime e

  url "javascript:
function a (v, t) { print ('O active ' + v + ' ' + t); }
function d (v, t) { print ('O duration ' + v + ' ' + t); }
function e (v, t) { print ('O elapsed ' + v + ' ' + t); }
"
}

ROUTE T.time TO S.set_time
ROUTE T.time TO K.set_time
ROUTE O.isActive TO PO.a
ROUTE O.duration_changed TO PO.d
ROUTE O.elapsedTime TO PO.e
